import{c as a,Q as n,j as s,m as r}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"DNA Language Models: An Assessment of Pre-Training for Fine-Tuning Tasks","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.30140","title":"DNA Language Models: An Assessment of Pre-Training for Fine-Tuning Tasks","archived_date":"2026-07-23T00:00:00.000Z","arxiv_id":2606.3014,"authors":["Romain Karpinsky","Julien Mozziconacci","Mickaël Delcey"],"domain":"genomic-biological-foundation-models","published_date":"2026-06-29T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-23-dna-language-model-pretraining-assessment-2606-30140.md","filePath":"research/papers/2026-07-23-dna-language-model-pretraining-assessment-2606-30140.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-07-23-dna-language-model-pretraining-assessment-2606-30140.md"};function t(o,e,l,d,g,u){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="dna-language-models-an-assessment-of-pre-training-for-fine-tuning-tasks" tabindex="-1">DNA Language Models: An Assessment of Pre-Training for Fine-Tuning Tasks <a class="header-anchor" href="#dna-language-models-an-assessment-of-pre-training-for-fine-tuning-tasks" aria-label="Permalink to &quot;DNA Language Models: An Assessment of Pre-Training for Fine-Tuning Tasks&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文（arXiv Quantitative Biology &gt; Genomics 分類）系統性評估 DNA 語言模型的預訓練對下游 fine-tuning 任務的實際貢獻度，比較 transformer-based 與傳統卷積式架構在基因體序列分析任務上的表現。核心發現對領域內「預訓練必然帶來下游增益」的預設提出質疑：部分任務上，預訓練帶來的提升相當有限，甚至不敵針對任務直接訓練的較簡單模型，顯示 DNA 語言模型的預訓練紅利可能存在遞減效應，且高度依賴任務類型與資料規模。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>DNA 語言模型預訓練效益的實證評估，與 workspace 現有版圖（agent harness、雲端 FinOps、K8s/Kafka 維運）無內容重疊；核心關鍵詞於既有覆蓋集合與既探勘新領域紀錄命中皆為 0。</p>',5)])])}const p=a(i,[["render",t]]);export{c as __pageData,p as default};
